def coins_greedy(amount, coins):
    taken = []
    for c in sorted(coins, reverse=True):
        while amount >= c:
            taken.append(c)
            amount -= c
    if amount != 0:
        return None
    return taken

def max_meetings(intervals):
    count = 0
    end = float('-inf')
    for s, e in sorted(intervals, key=lambda iv: iv[1]):
        if s >= end:
            count += 1
            end = e
    return count
